pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: prioritize bins that leave the smallest residual.
    // However, heavily penalize "sliver" residuals (1-9) that are unlikely to fit future items.
    if post_residual > 0 && post_residual < 10 {
        score += 45.0;
    }

    // 2. Harmonic Lookahead: If next_item_size is known, favor bins that accommodate it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins that can perfectly fit or leave minimal space for the next item.
            score -= (bin_capacity - post_residual) as f64 * 0.2;
        } else {
            // Penalize bins that force a new bin for the next item.
            score += 15.0;
        }
    }

    // 3. Pressure management: If we have many open bins, be more aggressive with Best-Fit.
    // If we have few open bins, prioritize creating tighter packs.
    score += (open_bins_count as f64) * 0.5;

    // 4. Thresholding: Avoid opening a new bin unless the fit is extremely poor.
    // If this is a new bin (bin_residual == bin_capacity), set a high baseline cost.
    if bin_residual == bin_capacity {
        score = 35.0 + (mean_residual * 0.1);

        // If there are bins that could fit this item, penalize opening a new one significantly.
        if fitting_bins_count > 0 {
            score += 40.0;
        }
    }

    // 5. Harmonic packing: Favor residuals that are multiples of common item sizes (e.g., 20, 25, 50).
    // This creates "bins of specific types" to increase the probability of future items fitting.
    let remainder = post_residual % 25;
    if remainder == 0 {
        score -= 5.0;
    }

    score
}

