    let is_new_bin = bin_residual == bin_capacity;

    // Base score: favor smaller remaining space (Best Fit)
    let mut score = post_residual as f64;

    // Penalty for opening new bins prematurely
    if is_new_bin {
        score += 45.0 + (progress * 20.0);
        // If we have plenty of open bins, discourage opening more
        score += (open_bins_count as f64) * 5.0;
    }

    // Lookahead logic: If the next item is large, favor bins that can accommodate it
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins that keep capacity for the next item
            score -= 15.0;
        } else if post_residual > 0 && post_residual < 20 {
            // Penalize creating "sliver" space that is too small for most items
            score += 25.0;
        }
    }

    // Global state adjustment: If mean residual is high, we are being too wasteful
    // Force tighter packing by penalizing bins that drift from the mean
    if (bin_residual as f64) > mean_residual {
        score += 5.0;
    }

    // Criticality check: If only one bin fits, prioritize it heavily to avoid new bin creation
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 50.0;
    }

    // Encourage filling bins to high density as we approach the end of the stream
    if progress > 0.8 {
        score -= (bin_capacity - post_residual) as f64 * 0.1;
    }

    score
