pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Penalty for creating "dead space": residuals that are too small to be useful
    // (Commonly 1-9 are useless since min item size is 10)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // 2. Lookahead optimization: If the next item is large, prioritize bins that can fit it
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins that maintain capacity for the next item
            score -= 15.0 * (1.0 - progress);
        } else if post_residual < next_item_size && post_residual >= 10 {
            // Penalty for stranding a bin that can't fit the next item
            score += 10.0;
        }
    }

    // 3. Global State Balancing:
    // If we have many open bins, prioritize filling them tightly (Best Fit).
    // If we have few, prioritize keeping bins empty/balanced (First Fit).
    let open_penalty = (open_bins_count as f64) * 2.0;
    if fitting_bins_count > 1 {
        score += open_penalty;
    } else {
        // If this is the last fitting bin, we are desperate; reduce penalty to avoid new bins
        score -= open_penalty * 0.5;
    }

    // 4. New Bin Logic:
    // Only open a new bin if the current post_residual is very poor (e.g., > 40)
    // or if we are nearing the end of the stream and need to consolidate.
    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            score = 0.0;
        } else {
            // Base cost of opening a new bin
            score = 45.0 + (mean_residual * 0.5);
            // If the stream is ending, discourage new bins heavily
            if progress > 0.8 {
                score += 50.0;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalty for creating "orphan" space that is too small for common items
    // (A bin with less than 10 remaining is rarely useful, as min item size is 10)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Aggressive 2-step lookahead: 
    // If next_item_size fits perfectly into the post_residual, reward heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual > next_item_size {
            // If post_residual is slightly larger than next_item_size, favor it
            // but penalize if it leaves a tiny unusable gap (e.g., 1-9 units)
            let gap = post_residual - next_item_size;
            if gap < 10 {
                score += 25.0;
            }
        }
    }

    // 3. Balancing bins: 
    // If this is the only bin that fits the current item (fitting_bins_count == 1),
    // we should prioritize using it unless it creates a very poor residual.
    if fitting_bins_count == 1 && post_residual < 15 {
        score -= 30.0;
    }

    // 4. Global distribution awareness:
    // If the bin's current residual is significantly lower than the mean_residual,
    // it is a "denser" bin. We prefer filling denser bins to keep others empty.
    if (bin_residual as f64) < mean_residual {
        score -= 10.0;
    }

    // 5. New Bin Thresholding:
    // If we are considering a new bin (bin_residual == bin_capacity),
    // we apply a heavy penalty to prevent opening it unless necessary.
    if bin_residual == bin_capacity {
        // Only open a new bin if we have many open bins already (high overhead)
        // or if the current progress is early (low risk).
        score += 60.0 - (open_bins_count as f64 * 0.5);
    }

    score
}

