pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for creating 'unusable' slivers: gaps between 1 and 9 are extremely hard to fill.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // Lookahead: If the next item is large and won't fit in the remaining space, 
    // penalize placements that leave just enough space to be tempting but not enough to be useful.
    if next_item_size > 0 && post_residual < next_item_size && post_residual >= 10 {
        score += 25.0;
    }

    // Pressure normalization: Increase cost of opening new bins as we progress through the stream.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        // High penalty for opening new bins; reduced slightly if we have many open bins already.
        score += 80.0 * (1.0 + progress) - (open_bins_count as f64 * 2.0);
    } else {
        // Reward bins that keep residuals closer to the global mean, 
        // effectively balancing the load across active bins.
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.5;
    }

    // If this is the only bin that fits, prioritize it heavily to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    score
}
